def parse_size(txt):
    m=re.search(r' (\\d+(?:\\.\\d+)?)([KMG])(?:\\s|"'$)'"', txt)
    if not m: return None
    return int(float(m.group(1))*{'K':1024,'M':1048576,'G':1073741824}[m.group(2)])

